def _get_mechanics():
    return [
        {"id":"mech_physics","name":"Physics Systems","category":"core","description":"Rigid body, soft body, cloth, fluid, destruction simulation.","implementations":["Box2D (2D physics)","Bullet Physics (3D)","PhysX (NVIDIA)","Havok","Jolt Physics"],"code":"# Basic physics step\nvelocity += acceleration * dt\nposition += velocity * dt\nacceleration = force / mass\n\n# Collision response\nnormal = contact_normal\nrelative_vel = vel_a - vel_b\nimpulse = -(1 + restitution) * dot(relative_vel, normal) / (1/mass_a + 1/mass_b)"},
        {"id":"mech_ai","name":"Game AI","category":"core","description":"NPC behavior, pathfinding, decision making.","implementations":["Behavior Trees","Finite State Machines","GOAP (Goal-Oriented Action Planning)","Utility AI","HTN Planning","Neural Networks"],"code":"# Behavior Tree nodes\nclass Selector: # Try children until one succeeds\nclass Sequence: # Run children until one fails\nclass Decorator: # Modify child behavior\n\n# A* Pathfinding\ndef astar(start, goal, graph):\n    open_set = {start}\n    g_score = {start: 0}\n    f_score = {start: heuristic(start, goal)}\n    while open_set:\n        current = min(open_set, key=lambda n: f_score[n])\n        if current == goal: return reconstruct_path()\n        for neighbor in graph[current]:\n            tentative = g_score[current] + cost(current, neighbor)\n            if tentative < g_score.get(neighbor, inf):\n                g_score[neighbor] = tentative\n                f_score[neighbor] = tentative + heuristic(neighbor, goal)\n                open_set.add(neighbor)"},
        {"id":"mech_networking","name":"Multiplayer Networking","category":"core","description":"Client-server architecture, prediction, synchronization.","implementations":["Dedicated Server","P2P","Relay Server","Rollback Netcode","Lockstep"],"code":"# Client-side prediction\ndef client_update(input):\n    predicted_state = simulate(current_state, input)\n    send_input_to_server(input)\n    render(predicted_state)\n\n# Server reconciliation\ndef on_server_state(server_state, last_processed_input):\n    rewind_to(server_state)\n    for input in unprocessed_inputs_after(last_processed_input):\n        simulate(input)  # Re-simulate with correct state"},
        {"id":"mech_animation","name":"Animation Systems","category":"visual","description":"Skeletal animation, blend trees, IK, ragdoll, motion matching.","implementations":["Skeletal Animation","Blend Trees","Inverse Kinematics","Ragdoll Physics","Motion Matching","Root Motion"],"code":"# Blend tree\nfinal_pose = lerp(idle_pose, walk_pose, speed / max_speed)\nif is_aiming:\n    upper_body = lerp(final_pose.upper, aim_pose, aim_weight)\n\n# IK (Inverse Kinematics)\n# FABRIK algorithm: iteratively adjust joint chain to reach target\ndef fabrik(chain, target, tolerance=0.01):\n    for _ in range(max_iterations):\n        backward_pass(chain, target)\n        forward_pass(chain, chain[0].position)\n        if distance(chain[-1], target) < tolerance: break"},
        {"id":"mech_audio","name":"Audio Systems","category":"core","description":"Spatial audio, mixing, dynamic music, sound design.","implementations":["FMOD","Wwise","OpenAL","Web Audio API","Unity Audio"],"code":"# 3D spatial audio\ndef calculate_volume(listener_pos, source_pos, max_distance):\n    distance = length(source_pos - listener_pos)\n    return max(0, 1 - distance / max_distance)\n\n# Dynamic music layers\nclass MusicSystem:\n    layers = [bass, drums, melody, intensity]\n    def update(self, combat_level):\n        for i, layer in enumerate(self.layers):\n            target_vol = 1.0 if combat_level > i * 0.25 else 0.0\n            layer.volume = lerp(layer.volume, target_vol, 0.05)"},
        {"id":"mech_procedural","name":"Procedural Generation","category":"core","description":"Algorithmic content creation: terrain, levels, items, quests.","implementations":["Perlin/Simplex Noise","Wave Function Collapse","L-Systems","Cellular Automata","BSP Tree","Voronoi","Marching Cubes"],"code":"# Perlin noise terrain\ndef generate_terrain(width, height, scale=50):\n    for x in range(width):\n        for y in range(height):\n            elevation = noise.pnoise2(x/scale, y/scale, octaves=6)\n            moisture = noise.pnoise2(x/scale+1000, y/scale+1000, octaves=4)\n            biome = get_biome(elevation, moisture)\n            terrain[x][y] = Tile(elevation, moisture, biome)\n\n# Wave Function Collapse\n# 1. Start with all tiles in superposition (all possibilities)\n# 2. Collapse tile with lowest entropy (fewest options)\n# 3. Propagate constraints to neighbors\n# 4. Repeat until all tiles collapsed"},
        {"id":"mech_rendering","name":"Rendering Pipeline","category":"visual","description":"Graphics pipeline from geometry to pixels.","implementations":["Forward Rendering","Deferred Rendering","Ray Tracing","PBR","Cel Shading","Voxel Rendering"],"code":"# PBR (Physically Based Rendering)\n# Cook-Torrance BRDF\ndef brdf(normal, view, light, albedo, metallic, roughness):\n    h = normalize(view + light)\n    D = distribution_ggx(normal, h, roughness)  # Microfacet distribution\n    F = fresnel_schlick(dot(h, view), f0)        # Fresnel reflection\n    G = geometry_smith(normal, view, light, roughness)  # Self-shadowing\n    specular = (D * F * G) / (4 * dot(normal, view) * dot(normal, light))\n    diffuse = albedo / pi * (1 - metallic)\n    return diffuse + specular"},
        {"id":"mech_ui","name":"Game UI/UX","category":"design","description":"HUD, menus, inventory, dialogue, accessibility.","implementations":["Immediate Mode GUI","Retained Mode GUI","Data-Driven UI","Reactive UI"],"code":"# Health bar\ndef render_health_bar(current_hp, max_hp, width=200):\n    ratio = current_hp / max_hp\n    color = lerp(RED, GREEN, ratio)\n    draw_rect(x, y, width * ratio, height, color)\n    draw_text(f'{current_hp}/{max_hp}', x + width/2, y)\n\n# Damage numbers\nclass DamagePopup:\n    def __init__(self, pos, amount, crit=False):\n        self.pos = pos\n        self.velocity = Vec2(random(-50,50), -200)\n        self.lifetime = 1.0\n        self.text = f'{amount}!' if crit else str(amount)\n    def update(self, dt):\n        self.pos += self.velocity * dt\n        self.velocity.y += 400 * dt  # gravity\n        self.lifetime -= dt"},
    ]

