def _get_design_patterns():
    return [
        {"id":"dp_game_loop","name":"Game Loop","description":"Fixed timestep for physics, variable for rendering.\nwhile running:\n    process_input()\n    while accumulated_time >= FIXED_DT:\n        physics_update(FIXED_DT)\n        accumulated_time -= FIXED_DT\n    render(interpolation_alpha)"},
        {"id":"dp_ecs","name":"Entity Component System","description":"Entities=IDs, Components=data, Systems=logic.\nSeparation of data and behavior for cache-friendly iteration."},
        {"id":"dp_state_machine","name":"State Machine","description":"Character states: Idle→Run→Jump→Fall→Attack.\nEach state handles enter/exit/update. Transitions based on conditions."},
        {"id":"dp_observer","name":"Observer / Event System","description":"Decouple game systems via events.\nevent_bus.emit('enemy_killed', {enemy, position, xp})\nevent_bus.on('enemy_killed', update_score)\nevent_bus.on('enemy_killed', spawn_particles)"},
        {"id":"dp_object_pool","name":"Object Pool","description":"Pre-allocate objects to avoid runtime allocation.\nBullets, particles, enemies reused from pool.\npool.get() → use → pool.return()"},
        {"id":"dp_command","name":"Command Pattern","description":"Encapsulate actions for undo/redo, replay, networking.\nclass MoveCommand { execute(), undo() }\ncommand_history.push(cmd); cmd.execute();"},
        {"id":"dp_spatial","name":"Spatial Partitioning","description":"Quadtree (2D) / Octree (3D) / Grid for efficient spatial queries.\nReduce collision checks from O(n²) to O(n log n)."},
        {"id":"dp_lod","name":"Level of Detail","description":"Reduce geometry/texture resolution based on distance.\nNear: full mesh. Mid: simplified. Far: billboard/impostor.\nNanite: automatic virtualized geometry LOD."},
    ]
